 vals={'all_required_fields':all(all(k in o for k in ('creator','debtor','beneficiary','expected_content','supports','status','contextual_deadline','history','rule')) for c in cases for o in c['candidates']),'not_conflated_with_private_state':all(o['record_type']=='discourse_obligation' and set(o['explicitly_not'])=={'belief','goal','intention'} for c in cases for o in c['candidates']),'lifecycle_outcomes_covered':{'satisfied','cancelled','violated','open'}<= {o['status'] for c in cases for o in c['candidates']},'digression_does_not_discharge':next(c for c in cases if c['id']=='digression-return')['candidates'][0]['history'][1]['status']=='open','silence_does_not_satisfy':next(c for c in cases if c['id']=='unsatisfied')['candidates'][0]['history'][1]['status']=='open','concurrent_hypotheses_preserved':next(c for c in cases if c['id']=='ambiguous-indirect-request')['selected'] is None and len(next(c for c in cases if c['id']=='ambiguous-indirect-request')['candidates'])==2,'all_rules_attributed':all(o['rule']['producer'] and o['rule']['version'] for c in cases for o in c['candidates'])};assert all(vals.values()),vals
